/* @component: .js-container-input */
(function () { 
  document.addEventListener('DOMContentLoaded', function () { 
    document.querySelectorAll('fieldset').forEach(function (fs) { 
      const label = fs.querySelector('label'); 
      const legendSpan = fs.querySelector('legend span'); 
      if (label && legendSpan) { 
        legendSpan.innerHTML = label.innerHTML; 
      } 
    }); 
  }); 
})();
